foundation.solution_text:
[tikz]
\begin{tikzpicture}\begin{axis}[width=6.5cm,height=6.5cm,axis lines=middle,axis line style={-{Stealth}},xmin=-1,xmax=9,ymin=-4,ymax=4,xtick={2,4,6,8},ytick={-4,-2,2,4},grid=both,clip=false,scaled ticks=false,ticklabel style={font=\small,/pgf/number format/fixed},xlabel={$x$},ylabel={$y$}]
